import json, subprocess
old = subprocess.run(['git','show','HEAD:.coding-hermes/board/tasks.jsonl'],capture_output=True,text=True).stdout.splitlines()
new = open('.coding-hermes/board/tasks.jsonl').read().splitlines()
def rowmap(lines):
    out={}
    for l in lines:
        try: r=json.loads(l)
        except Exception: continue
        out[r.get('id')]=r
    return out
o,n = rowmap(old), rowmap(new)
for rid in set(o)|set(n):
    a,b = o.get(rid), n.get(rid)
    if a!=b:
        keys = [k for k in set((a or {}).keys())|set((b or {}).keys()) if (a or {}).get(k)!=(b or {}).get(k)]
        print(rid, "changed keys:", keys)
EOF
